<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { api, rows } from '../api'
import { number, pct } from '../format'
import { COMMON_COLORS, COMMON_SIZES, uniqueOptions } from '../spec-options'
import AppIcon from '../components/AppIcon.vue'
import PageState from '../components/PageState.vue'
import BundleMatrixEditor from '../components/BundleMatrixEditor.vue'
import { bundleCompletionMatrix } from '../order-matrix'
import TicketPrintDialog from '../components/TicketPrintDialog.vue'

const loading = ref(true), error = ref(''), data = ref({ count: 0 }), detail = ref(null), bundles = ref(null), detailError = ref('')
const mobileRows = ref([]), loadingMore = ref(false), moreError = ref(''), hasMore = ref(false)
const filters = reactive({ keyword: '', is_locked: '', is_cut_done: '', page: 1 })
const productionFilters = [
  { key: 'all', label: '全部', is_locked: '', is_cut_done: '' },
  { key: 'uncut', label: '未裁完', is_locked: '', is_cut_done: '0' },
  { key: 'cut', label: '已裁完', is_locked: '', is_cut_done: '1' },
  { key: 'locked', label: '已锁定', is_locked: '1', is_cut_done: '' },
]
const props = defineProps({ section: { type: String, default: '' } })
const emit = defineEmits(['toast', 'navigate'])
const printing = ref(false)
const editor = ref(''), saving = ref(false), editError = ref(''), options = reactive({ styles: [], customers: [], orders: [], processes: [], lots: [], nextBedNo: '' })
const form = reactive({ id: null, bed_no: '', style: '', customer: '', order_id: '', order_type: '自产', fabric: '', source_order_no: '', plan_qty: '', bom_bypass: false, bypass_reason: '', process_items: [], items: [{ color: '', size: '', qty: 20 }], bundle_limit: 20, start_bundle_no: '' })
const bundleOptions = reactive({ colors: [], sizes: [], orderItems: [], loading: false, blocked: false, note: '' })
const bundleColors = computed(() => uniqueOptions(
  bundleOptions.orderItems.map((item) => item.color),
  bundleOptions.orderItems.length ? [] : (bundles.value?.results || []).map((ticket) => ticket.color),
  bundleOptions.orderItems.length ? [] : bundleOptions.colors,
  bundleOptions.orderItems.length ? [] : COMMON_COLORS,
))
const bundleTotal = computed(() => form.items.reduce((total, item) => total + (Number(item.qty) || 0), 0))
const completionMatrix = computed(() => bundleCompletionMatrix(bundles.value?.results || []))
const remainingBySpec = computed(() => Object.fromEntries((bundleOptions.orderItems || []).map((item) => [`${item.color}|${item.size}`, Number(item.remaining ?? item.qty) || 0])))
function bundleSizesFor(color) {
  if (bundleOptions.orderItems.length) return uniqueOptions(bundleOptions.orderItems.filter((item) => !color || item.color === color).map((item) => item.size))
  return uniqueOptions((bundles.value?.results || []).filter((ticket) => !color || ticket.color === color).map((ticket) => ticket.size), bundleOptions.sizes, COMMON_SIZES)
}
async function loadOptions() { const [styles,customers,orders,processes,recent]=await Promise.all([api('/styles',{params:{page_size:200}}),api('/customers',{params:{page_size:200}}),api('/orders',{params:{page_size:200,status:'producing'}}),api('/processes',{params:{page_size:200}}),api('/productions',{params:{page_size:1}})]);options.styles=rows(styles);options.customers=rows(customers);options.orders=rows(orders);options.processes=rows(processes);const last=rows(recent)[0];options.nextBedNo=last&&/^\d+$/.test(String(last.bed_no||''))?String(Number(last.bed_no)+1):'' }
function processItems(source) { return (source || []).map((p) => ({ process_id: p.process_id ?? p.process, price: p.price ?? '0' })) }
function productionStyleChanged() { const style=options.styles.find((item)=>item.id===Number(form.style));if(!style)return;form.customer=style.customer||form.customer;form.fabric=style.fabric||'';if(!form.id&&!form.order_id)form.process_items=processItems(style.processes) }
function productionOrderChanged() { const order=options.orders.find((item)=>item.id===Number(form.order_id));if(!order)return;const style=options.styles.find((item)=>item.id===Number(order.style));Object.assign(form,{style:order.style||form.style,customer:order.customer||form.customer,order_type:order.order_type||'自产',source_order_no:order.order_no||'',plan_qty:order.total_qty||(order.items||[]).reduce((sum,item)=>sum+Number(item.qty||0),0),fabric:style?.fabric||form.fabric,process_items:processItems(order.process_items?.length?order.process_items:style?.processes)}) }
async function openCreate() { Object.assign(form,{id:null,bed_no:'',style:'',customer:'',order_id:'',order_type:'自产',fabric:'',source_order_no:'',plan_qty:'',bom_bypass:false,bypass_reason:'',process_items:[],items:[{color:'',size:'',qty:20}],bundle_limit:20,start_bundle_no:''});editor.value='create';editError.value='';try{await loadOptions();if(!form.bed_no)form.bed_no=options.nextBedNo}catch(e){editError.value=e.message} }
async function openEdit() { const full=await api(`/productions/${detail.value.id}`);Object.assign(form,{id:full.id,bed_no:full.bed_no,style:full.style||'',customer:full.customer||'',order_id:full.order||'',order_type:full.order_type||'自产',fabric:full.fabric||'',source_order_no:full.source_order_no||'',plan_qty:full.plan_qty||'',bom_bypass:false,bypass_reason:'',process_items:(full.order_processes||[]).map(p=>({process_id:p.process,price:p.price})),items:[{color:'',size:'',qty:20}],bundle_limit:20,start_bundle_no:''});editor.value='edit';editError.value='';try{await loadOptions()}catch(e){editError.value=e.message} }
function blankBundleItem() { return { color: '', size: '', qty: 20 } }
function addBundleItem() { const used=new Set(form.items.map((item)=>`${item.color}|${item.size}`));const next=bundleOptions.orderItems.find((item)=>!used.has(`${item.color}|${item.size}`));form.items.push(next?{color:next.color,size:next.size,qty:20}:blankBundleItem()) }
function bundleColorChanged(item) { const sizes=bundleSizesFor(item.color);if(!sizes.includes(item.size))item.size=sizes.length===1?sizes[0]:'' }
async function openBundles(){
  Object.assign(form,{items:[],bundle_limit:20,start_bundle_no:''})
  Object.assign(bundleOptions,{colors:[],sizes:[],orderItems:[],loading:true,blocked:false,note:''})
  editor.value='bundles';editError.value=''
  const orderId=detail.value.order
  const [colorResult,hintResult,orderResult,progressResult]=await Promise.allSettled([
    api('/production-colors'),api('/production-hints'),
    orderId?api(`/orders/${orderId}`):Promise.resolve(null),
    orderId?api(`/orders/${orderId}/progress`):Promise.resolve(null),
  ])
  if(colorResult.status==='fulfilled')bundleOptions.colors=rows(colorResult.value).map((item)=>item.name)
  if(hintResult.status==='fulfilled')bundleOptions.sizes=(hintResult.value.sizes||[]).map((item)=>item.name)
  const order=orderResult.status==='fulfilled'?orderResult.value:null
  bundleOptions.orderItems=order?.items||[]
  if(order){
    if(!bundleOptions.orderItems.length){
      bundleOptions.blocked=true
      bundleOptions.note='订单尚未维护颜色与尺码，请先在订单明细中补齐后再编菲。'
    }else if(progressResult.status==='fulfilled'){
      const progressItems=progressResult.value.items||progressResult.value.cells||[]
      const progressBySpec=new Map(progressItems.map((item)=>[`${item.color}|${item.size}`,item]))
      const remaining=bundleOptions.orderItems.map((item)=>{const progress=progressBySpec.get(`${item.color}|${item.size}`);const remainingQty=Math.max(Number(item.qty||0)-Number(progress?.cut_qty||0),0);return {...item,qty:remainingQty,remaining:remainingQty}})
      bundleOptions.orderItems=remaining
      form.items=remaining.filter((item)=>item.qty>0).map((item)=>({color:item.color,size:item.size,qty:item.qty}))
      bundleOptions.note=remaining.length?`已按订单 ${order.order_no} 的未裁数量带出 ${remaining.length} 个色码，可直接调整。`:'订单各色码当前均未显示可裁余量；如需加扎，请点“添加色码”后选择并填写数量。'
    }else{
      form.items=[]
      bundleOptions.note='订单余量读取失败，未自动填入数量，以免重复编菲；请重试，或点“添加色码”后人工核对数量。'
    }
  }else if(orderId){
    bundleOptions.blocked=true
    bundleOptions.note='订单色码读取失败，请关闭后重试；读取成功前不会生成菲票。'
    editError.value=`订单色码读取失败：${orderResult.reason.message}`
  }else{
    bundleOptions.note='未关联订单：选项来自本床已用色码、厂内历史和常用规格，点选即可，无需输入。'
    form.items=[blankBundleItem()]
  }
  bundleOptions.loading=false
}
async function openLotLinks(){editor.value='lots';editError.value='';form.lot_items=[];try{const[lots,links]=await Promise.all([api('/lots',{params:{page_size:200}}),api(`/productions/${detail.value.id}/lot-links`)]);options.lots=rows(lots);form.lot_items=links.map(link=>({lot_id:link.lot,qty:String(link.qty)}))}catch(e){editError.value=e.message}}
async function saveLotLinks(){const items=form.lot_items.filter(item=>item.lot_id);if(new Set(items.map(item=>Number(item.lot_id))).size!==items.length){editError.value='同一批次不能重复关联';return}if(items.some(item=>!Number.isFinite(Number(item.qty))||Number(item.qty)<0)){editError.value='批次用量须为不小于 0 的数字';return}saving.value=true;editError.value='';try{await api(`/productions/${detail.value.id}/lot-links`,{method:'PUT',body:{items:items.map(item=>({lot_id:Number(item.lot_id),qty:String(item.qty||0)}))}});editor.value=null;emit('toast','床次面料批次已保存')}catch(e){editError.value=e.message}finally{saving.value=false}}
async function saveProduction(){if(!form.bed_no.trim()||!form.style){editError.value='请填写床次号并选择款式';return};saving.value=true;editError.value='';const body={bed_no:form.bed_no,style:Number(form.style),customer:form.customer?Number(form.customer):null,order_id:form.order_id?Number(form.order_id):undefined,order_type:form.order_type,fabric:form.fabric,source_order_no:form.source_order_no,plan_qty:form.plan_qty?Number(form.plan_qty):null};if(form.id||form.process_items.some(p=>p.process_id))body.process_items=form.process_items.filter(p=>p.process_id).map(p=>({process_id:Number(p.process_id),price:String(p.price||0)}));if(form.bom_bypass){body.bom_bypass=true;body.bypass_reason=form.bypass_reason}try{const result=await api(form.id?`/productions/${form.id}`:'/productions',{method:form.id?'PUT':'POST',body});editor.value=null;emit('toast',form.id?'床次已保存':'床次已创建');detail.value=null;load();if(!form.id)open(result)}catch(e){editError.value=e.message}finally{saving.value=false}}
async function createTickets(){if(bundleOptions.blocked){editError.value='订单色码尚未读取，请关闭后重试';return}const items=form.items.filter(i=>i.color&&i.size).map(i=>({...i,qty:Number(i.qty)}));if(!items.length||items.some(i=>!Number.isInteger(i.qty)||i.qty<=0)){editError.value='请选择颜色、尺码并填写正整数数量';return}const keys=items.map((item)=>`${item.color}|${item.size}`);if(new Set(keys).size!==keys.length){editError.value='同一颜色尺码不能重复，请合并数量';return}if(bundleOptions.orderItems.length&&items.some((item)=>!bundleOptions.orderItems.some((spec)=>spec.color===item.color&&spec.size===item.size))){editError.value='颜色与尺码必须按订单中的组合选择';return}if(!Number.isInteger(Number(form.bundle_limit))||Number(form.bundle_limit)<=0){editError.value='每扎上限须为正整数';return}for(const item of items){const key=`${item.color}|${item.size}`,remaining=Number(remainingBySpec.value[key]||0);if(bundleOptions.orderItems.length&&item.qty>remaining&&!confirm(`${item.color} / ${item.size} 本次 ${item.qty} 件，订单可裁余量 ${remaining} 件，超出 ${item.qty-remaining} 件。确认仍要生成？后端仍会执行数量门禁。`))return}saving.value=true;editError.value='';try{const created=await api('/tickets/batch',{method:'POST',body:{production_id:detail.value.id,items,bundle_limit:Number(form.bundle_limit),start_bundle_no:form.start_bundle_no||undefined}});editor.value=null;emit('toast',`已生成 ${created.length} 扎菲票`);await open(detail.value);load()}catch(e){editError.value=e.message}finally{saving.value=false}}
async function toggle(kind){const locked=kind==='lock'?!detail.value.is_locked:undefined;const cut=kind==='cut'?!detail.value.is_cut_done:undefined;if(!confirm(`确认${kind==='lock'?(locked?'锁定':'解锁'):(cut?'标记裁完':'取消裁完')}床次 ${detail.value.bed_no}？`))return;try{await api(`/productions/${detail.value.id}/${kind==='lock'?'lock':'cut-done'}`,{method:'PUT',body:kind==='lock'?{locked}:{is_cut_done:cut}});emit('toast','床次状态已更新');await open(detail.value);load()}catch(e){detailError.value=e.message}}
async function removeProduction(){if(!confirm(`确认删除床次 ${detail.value.bed_no}？其下菲票会一并删除；已有未撤销登记时后端会拒绝。`))return;try{await api(`/productions/${detail.value.id}`,{method:'DELETE'});detail.value=null;emit('toast','床次及菲票已删除');load()}catch(e){detailError.value=e.message}}
let timer, listRequest = 0
function progress(item) { return item.ticket_count ? pct(item.done_ticket_count / item.ticket_count * 100) : 0 }
function setProductionFilter(item) { filters.is_locked=item.is_locked;filters.is_cut_done=item.is_cut_done;filters.page=1;load() }
async function load() {
  const serial = ++listRequest
  loading.value = true; error.value = ''; moreError.value = ''; loadingMore.value = false; hasMore.value = false; mobileRows.value = []
  try {
    const result = await api('/productions', { params: { ...filters, page_size: 20 } })
    if (serial !== listRequest) return
    data.value = result
    mobileRows.value = rows(result)
    hasMore.value = result.next !== undefined ? Boolean(result.next) : filters.page * 20 < (result.count || 0)
  } catch (e) {
    if (serial === listRequest) error.value = e.message
  } finally {
    if (serial === listRequest) loading.value = false
  }
}
async function loadMore() {
  if (loading.value || loadingMore.value || !hasMore.value) return
  const serial = listRequest, page = filters.page + 1
  loadingMore.value = true; moreError.value = ''
  try {
    const result = await api('/productions', { params: { ...filters, page, page_size: 20 } })
    if (serial !== listRequest) return
    data.value = result
    mobileRows.value = mobileRows.value.concat(rows(result))
    filters.page = page
    hasMore.value = result.next !== undefined ? Boolean(result.next) : page * 20 < (result.count || 0)
  } catch (e) {
    if (serial === listRequest) moreError.value = e.message
  } finally {
    if (serial === listRequest) loadingMore.value = false
  }
}
function search() { clearTimeout(timer); timer = setTimeout(() => { filters.page = 1; load() }, 300) }
async function open(item) { detail.value = item; bundles.value = null; detailError.value = ''; try { detail.value = await api(`/productions/${item.id}`); bundles.value = await api(`/productions/${item.id}/bundles`, { params: { expand: 1 } }) } catch (e) { detailError.value = e.message } }
onMounted(async () => {
  await load()
  if (props.section.startsWith('create-')) {
    await openCreate()
    form.order_id = props.section.slice(7)
    productionOrderChanged()
  } else if (props.section) {
    try { await open(await api(`/productions/${Number(props.section)}`)) } catch (e) { error.value = e.message }
  }
})
</script>

<template>
  <div class="welcome production-welcome"><div><h2>生产床次</h2><p>开床、编菲、配置工序并跟踪扎级完工情况。</p></div><div class="production-head-actions"><button class="button secondary production-refresh" @click="load"><AppIcon name="refresh" :size="16" />刷新</button><button class="button primary" @click="openCreate">新建床次</button></div></div>
  <div class="filter-bar production-filter"><label class="search-box"><AppIcon name="search" :size="17" /><input v-model="filters.keyword" placeholder="搜索床次号、款号或客户" @input="search" /></label><div class="production-filter-chips" aria-label="床次状态筛选"><button v-for="item in productionFilters" :key="item.key" type="button" :class="{ active: filters.is_locked === item.is_locked && filters.is_cut_done === item.is_cut_done }" @click="setProductionFilter(item)">{{ item.label }}</button></div></div>
  <section class="card table-card production-list-card"><PageState :loading="loading" :error="error" :empty="!rows(data).length" empty-text="暂无生产床次" @retry="load"><div class="table-wrap desktop-table"><table><thead><tr><th>床次 / 关联订单</th><th>款式</th><th class="numeric">裁货数</th><th>完工扎进度</th><th class="numeric">登记工序量</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="item in rows(data)" :key="item.id" class="clickable" @click="open(item)"><td><span class="cell-title">{{ item.bed_no }}</span><small class="cell-subtitle">{{ item.order_no || item.source_order_no || '未关联订单' }}</small></td><td>{{ item.style_no }}<small class="cell-subtitle">{{ item.style_name }}</small></td><td class="numeric">{{ number(item.cut_total || item.total_qty) }}</td><td><div class="row-progress"><div class="meter-track"><div class="meter-fill" :style="{ width: `${progress(item)}%` }" /></div><span>{{ item.done_ticket_count || 0 }}/{{ item.ticket_count || 0 }}</span></div></td><td class="numeric">{{ number(item.registered_qty) }}</td><td><span class="badge" :class="item.is_locked ? 'cancelled' : 'producing'">{{ item.is_locked ? '已锁定' : item.is_cut_done ? '已裁完' : '生产中' }}</span></td><td><AppIcon name="chevron" :size="16" /></td></tr></tbody></table></div>
    <div class="mobile-cards"><button v-for="item in mobileRows" :key="item.id" class="mobile-row production-mobile-card" @click="open(item)"><img v-if="item.style_image" class="production-thumb" :src="item.style_image" :alt="`${item.style_name || item.style_no}款式图`" /><div class="production-card-main"><div class="mobile-row-head"><div class="production-title-line"><span class="mobile-row-title">床次 {{ item.bed_no }}</span><span v-if="item.is_locked" class="badge cancelled">已锁定</span><span v-if="item.is_cut_done" class="badge done">裁完</span></div><AppIcon name="chevron" :size="16" /></div><div class="production-style-line"><strong>{{ item.style_no }}</strong><span>{{ item.style_name }}</span></div><div class="production-mobile-stats"><span>总量 <b>{{ number(item.total_qty || item.cut_total) }}</b> 件</span><span>菲票 <b>{{ item.ticket_count || 0 }}</b> 扎</span><span>已登记 <b>{{ number(item.registered_qty) }}</b> 件</span></div><div v-if="item.customer_name || item.fabric" class="production-mobile-meta"><span v-if="item.customer_name">客户：{{ item.customer_name }}</span><span v-if="item.fabric">面料：{{ item.fabric }}</span></div></div></button></div></PageState><div class="pagination desktop-pagination"><button class="button ghost small" :disabled="filters.page <= 1" @click="filters.page--; load()">上一页</button><span>第 {{ filters.page }} 页 · 共 {{ data.count || 0 }} 条</span><button class="button ghost small" :disabled="filters.page * 20 >= (data.count || 0)" @click="filters.page++; load()">下一页</button></div><div v-if="mobileRows.length" class="mobile-list-more"><p v-if="moreError" class="mobile-more-error" role="alert">{{ moreError }} <button type="button" @click="loadMore">重试</button></p><button v-else-if="hasMore" class="mobile-load-more" type="button" :disabled="loadingMore" @click="loadMore"><span v-if="loadingMore" class="spinner" />{{ loadingMore ? '加载中…' : '加载更多' }}</button><p v-else class="mobile-no-more">没有更多了</p></div></section>

  <Teleport to="body"><div v-if="detail" class="modal-backdrop" @click.self="detail = null"><section class="modal production-detail-modal" role="dialog" aria-modal="true" :aria-label="`床次 ${detail.bed_no}`"><div class="modal-header"><div><h2>{{ detail.bed_no }} · 按扎明细</h2><p>{{ detail.style_no }} · {{ detail.style_name }}</p></div><button class="icon-button" aria-label="关闭" @click="detail = null"><AppIcon name="close" /></button></div><ol class="mobile-task-steps"><li class="active">床次信息</li><li>菲票与工序</li><li>编菲打印</li></ol><div class="mobile-production-info"><div><span>关联订单</span><strong>{{ detail.order_no || detail.source_order_no || '未关联订单' }}</strong></div><div><span>订单类型</span><strong>{{ detail.order_type || '自产' }}</strong></div><div><span>面料</span><strong>{{ detail.fabric || '—' }}</strong></div><div v-if="detail.plan_qty"><span>计划裁货</span><strong>{{ number(detail.plan_qty) }} 件</strong></div></div><div class="detail-grid"><div class="detail-item"><small>菲票数</small><strong>{{ detail.ticket_count || 0 }} 扎</strong></div><div class="detail-item"><small>完工扎</small><strong>{{ detail.done_ticket_count || 0 }} 扎</strong></div><div class="detail-item"><small>登记工序量</small><strong>{{ number(detail.registered_qty) }}</strong></div></div><div v-if="detailError" class="form-error">{{ detailError }}</div><div v-else-if="!bundles" class="page-state"><span class="spinner" />正在读取菲票…</div><template v-else><section v-if="detail.order_processes?.length" class="mobile-production-processes"><div class="mobile-section-heading"><h3>订单工序</h3><span>可覆盖款式单价</span></div><div v-for="process in detail.order_processes" :key="process.id || process.process"><span>{{ process.process_name || `工序 ${process.process}` }}</span><strong>{{ process.price }} 元/件</strong></div></section><div class="table-wrap desktop-detail-bundles"><table><thead><tr><th>扎号</th><th>颜色 / 尺码</th><th class="numeric">数量</th><th class="numeric">登记量</th><th>状态</th></tr></thead><tbody><tr v-for="ticket in bundles.results" :key="ticket.id"><td class="cell-title">{{ ticket.bundle_no }}</td><td>{{ ticket.color }} / {{ ticket.size }}</td><td class="numeric">{{ ticket.qty }}</td><td class="numeric">{{ ticket.registered_qty }}</td><td><span class="badge" :class="ticket.state === 'done' ? 'done' : ticket.state === 'partial' ? 'producing' : ''">{{ ticket.state_display || '未登记' }}</span></td></tr></tbody></table></div><section class="mobile-production-bundles"><div class="mobile-section-heading"><h3>菲票列表</h3><span>{{ bundles.results.length }} 扎</span></div><article v-for="ticket in bundles.results" :key="`mobile-${ticket.id}`" class="mobile-bundle-card"><div class="mobile-bundle-head"><strong>扎号：{{ ticket.bundle_no }}</strong><span :class="{ printed: ticket.is_printed }">{{ ticket.is_printed ? '已打印' : '未打印' }}</span></div><dl><div><dt>颜色</dt><dd>{{ ticket.color }}</dd></div><div><dt>尺码</dt><dd>{{ ticket.size }}</dd></div><div><dt>件数</dt><dd>{{ ticket.qty }}</dd></div><div><dt>登记量</dt><dd>{{ ticket.registered_qty }}</dd></div></dl><div class="mobile-bundle-state"><span class="badge" :class="ticket.state === 'done' ? 'done' : ticket.state === 'partial' ? 'producing' : ''">{{ ticket.state_display || '未登记' }}</span><small v-if="ticket.qr_code">{{ ticket.qr_code }}</small></div></article><p v-if="!bundles.results.length" class="mobile-empty-copy">该床次暂无菲票，编菲后自动生成</p></section></template><p class="section-note">完工扎 = 该扎已登记工序数达到床次配置工序数。</p><div class="form-actions"><button class="button danger" @click="removeProduction">删除床次</button><button class="button secondary" @click="openEdit">编辑床次/工序</button><button class="button secondary" @click="openBundles">编菲加扎</button><button class="button secondary" @click="openLotLinks">面料批次</button><button class="button secondary" :disabled="!bundles?.results?.length" @click="printing=true">打印菲票</button><button class="button secondary" @click="toggle('cut')">{{detail.is_cut_done?'取消裁完':'标记裁完'}}</button><button class="button primary" @click="toggle('lock')">{{detail.is_locked?'解锁床次':'锁定床次'}}</button></div></section></div></Teleport>

  <Teleport to="body"><div v-if="editor" class="modal-backdrop" @click.self="editor=null"><section class="modal production-editor-modal" role="dialog" aria-modal="true"><div class="modal-header"><h2>{{editor==='create'?'新建床次':editor==='edit'?'编辑床次与工序':editor==='lots'?'关联面料批次':'编菲加扎'}}</h2><button class="icon-button" aria-label="关闭" @click="editor=null"><AppIcon name="close" /></button></div><form v-if="['create','edit'].includes(editor)" @submit.prevent="saveProduction"><div class="mobile-form-section"><div class="form-grid"><label class="field"><span>床次号 *</span><input v-model="form.bed_no" required placeholder="数字床次自动顺延，也可自定义" /></label><label class="field"><span>关联订单</span><select v-model="form.order_id" @change="productionOrderChanged"><option value="">不关联订单</option><option v-for="o in options.orders" :key="o.id" :value="o.id">{{o.order_no}} · {{o.style_no}}</option></select></label><label class="field"><span>款式 *</span><select v-model="form.style" :disabled="Boolean(form.order_id)" @change="productionStyleChanged"><option value="">选择款式</option><option v-for="s in options.styles" :key="s.id" :value="s.id">{{s.style_no}} · {{s.name}}</option></select></label><label class="field"><span>客户</span><select v-model="form.customer"><option value="">不指定</option><option v-for="c in options.customers" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label class="field"><span>订单类型</span><select v-model="form.order_type"><option>自产</option><option>外发</option></select></label><label class="field"><span>计划裁货数</span><input v-model.number="form.plan_qty" type="number" min="0" /></label><label class="field"><span>面料</span><input v-model="form.fabric" /></label><label class="field"><span>来源单号</span><input v-model="form.source_order_no" :readonly="Boolean(form.order_id)" :placeholder="form.order_id ? '随关联订单自动带出' : '无订单时可填写外部来源单号'" /></label></div></div><div class="mobile-form-section"><div class="card-header production-editor-head"><h3>床次工序工价</h3><button type="button" class="button secondary small" @click="form.process_items.push({process_id:'',price:'0'})">添加工序</button></div><div v-for="(p,i) in form.process_items" :key="i" class="production-process-editor"><select v-model="p.process_id"><option value="">选择工序</option><option v-for="op in options.processes" :key="op.id" :value="op.id">{{op.name}}</option></select><input v-model="p.price" type="number" min="0" step="0.001" aria-label="工价" /><button type="button" class="icon-button" aria-label="删除工序" @click="form.process_items.splice(i,1)"><AppIcon name="close" :size="16" /></button></div></div><label v-if="!form.id" class="bypass-check"><input v-model="form.bom_bypass" type="checkbox" />无生效 BOM 时申请留痕放行</label><label v-if="form.bom_bypass" class="field bypass-reason"><span>放行原因</span><textarea v-model="form.bypass_reason" required /></label><p v-if="editError" class="form-error">{{editError}}</p><div class="form-actions"><button type="button" class="button secondary" @click="editor=null">取消</button><button class="button primary" :disabled="saving">保存床次</button></div></form><form v-else-if="editor==='bundles'" @submit.prevent="createTickets">
  <p class="section-note bundle-note">为床次 {{detail.bed_no}} 按颜色尺码生成菲票；每扎上限会自动拆出尾扎。</p>
  <p class="section-note bundle-source">{{ bundleOptions.note }}</p>
  <div v-if="bundleOptions.loading" class="page-state"><span class="spinner" />正在读取订单色码与常用规格…</div>
  <template v-else>
    <div v-for="(item,i) in form.items" :key="i" class="production-bundle-editor">
      <select v-model="item.color" aria-label="颜色" required @change="bundleColorChanged(item)"><option value="">选择颜色</option><option v-for="color in bundleColors" :key="color" :value="color">{{ color }}</option></select>
      <select v-model="item.size" aria-label="尺码" required><option value="">选择尺码</option><option v-for="size in bundleSizesFor(item.color)" :key="size" :value="size">{{ size }}</option></select>
      <input v-model.number="item.qty" type="number" min="1" step="1" aria-label="数量" required />
      <button type="button" class="icon-button" aria-label="删除色码" @click="form.items.splice(i,1)"><AppIcon name="close" :size="16" /></button>
    </div>
    <p v-if="!form.items.length" class="page-state bundle-empty">暂无待编菲色码，点下方“添加色码”选择。</p>
    <button type="button" class="button secondary small" :disabled="bundleOptions.blocked" @click="addBundleItem">添加色码</button>
    <div class="form-grid bundle-limits"><label class="field"><span>每扎上限</span><input v-model.number="form.bundle_limit" type="number" min="1" step="1" required /></label><label class="field"><span>起始扎号（留空自动）</span><input v-model="form.start_bundle_no" type="number" min="1" /></label></div>
    <p v-if="form.items.length" class="section-note bundle-total">本次共 {{ bundleTotal }} 件，将按每扎上限自动拆扎。</p>
  </template>
  <p v-if="editError" class="form-error">{{editError}}</p>
  <div class="form-actions"><button type="button" class="button secondary" @click="editor=null">取消</button><button class="button primary" :disabled="saving || bundleOptions.loading || bundleOptions.blocked">{{ saving ? '生成中…' : '生成菲票' }}</button></div>
</form><form v-else @submit.prevent="saveLotLinks"><p class="section-note lot-note">整表维护床次与面料批次的追溯关系；领料确认产生的关联也会被读取，保存前请核对。</p><div v-for="(item,index) in form.lot_items" :key="index" class="production-lot-editor"><select v-model="item.lot_id"><option value="">选择批次</option><option v-for="lot in options.lots" :key="lot.id" :value="lot.id">{{lot.lot_no}} · {{lot.fabric_name}} · {{lot.color}}（{{lot.qty}} {{lot.unit}}）</option></select><input v-model="item.qty" type="number" min="0" step="0.01" aria-label="批次用量" /><button type="button" class="icon-button" aria-label="删除批次行" @click="form.lot_items.splice(index,1)"><AppIcon name="close" :size="16" /></button></div><button type="button" class="button secondary small" @click="form.lot_items.push({lot_id:'',qty:'0'})">添加批次</button><p v-if="!options.lots.length" class="section-note">暂无库存批次，可先在采购仓库登记或导入期初库存。</p><p v-if="editError" class="form-error">{{editError}}</p><div class="form-actions"><button type="button" class="button secondary" @click="editor=null">取消</button><button class="button primary" :disabled="saving">保存批次关系</button></div></form></section></div></Teleport>
  <TicketPrintDialog v-if="printing" :tickets="bundles.results" :production="detail" @close="printing=false" @toast="emit('toast',$event)" />
</template>

